     "origin": "invented / adapted / cited のいずれか", "citation": "引用（cited の場合は必須）"}
  ],
  "apocrypha": ["異説として扱う言い伝え（出来事の題・結果・痕跡のいずれかにも現れるもの）"],
  "knowledge": {"人物ID": {"knows": ["ev-1"], "unknown": ["ev-2"]}},
  "notes": ""
